#pragma once

#include <sstream>
#include <string>

template <typename Range>
std::string join(const Range& range, const std::string& sep) {
  std::ostringstream out;
  bool first = true;
  for (const auto& item : range) {
    if (!first) out << sep;
    out << item;
    first = false;
  }
  return out.str();
}

